from flask import Flask, jsonify, request
import threading
import time

app = Flask(__name__)

# Shared state — a threading.Event signals when new data exists
_event = threading.Event()
_data = {"value": None}

@app.route("/poll")
def long_poll():
    """Client waits up to 30s. Returns immediately if data already waiting."""
    arrived = _event.wait(timeout=30)        # Block the request thread
    if arrived:
        _event.clear()                       # Reset for next poll cycle
        return jsonify({"data": _data["value"], "timeout": False})
    return jsonify({"data": None, "timeout": True})

@app.route("/publish", methods=["POST"])
def publish():
    """Push side: write new data and wake all waiting pollers."""
    _data["value"] = request.json.get("value")
    _event.set()                             # Wake every thread blocked on .wait()
    return jsonify({"ok": True})

